CustomField.formula:
/*If Primary User on the parent Gong Conversation is blank, display blank otherwise display a link to the User record of the Primary User on the Gong Conversation*/

IF(
  ISBLANK( Gong__Gong_Interaction__r.Gong__Primary_User__c ), 
  null, 
   HYPERLINK("/" &  Gong__Gong_Interaction__r.Gong__Primary_User__r.Id ,Gong__Gong_Interaction__r.Gong__Primary_User__r.FirstName & " " &  Gong__Gong_Interaction__r.Gong__Primary_User__r.LastName , "_blank")
)
